      b = (xion[j - 1] * yion[j] - xion[j] * yion[j - 1]) / (xion[j - 1] - xion[j])
      q[3, i] = (a * en + b) * 1e-16
    # ATTACHMENT
    q[4, i] = 0.0
    qatt[1, i] = q[4, i]
    block L300:
